insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('cuanto-cuesta-una-cola-el-valor-del-tiempo-perdido-en-un-tramite','negocios',array['ciudades','industria']::text[],'¿Cuánto cuesta una cola? El valor del tiempo perdido en un trámite','Mide cuánto tiempo pasan las personas esperando en un trámite o servicio, conviértelo en un costo y propón cambios que reduzcan la espera.','Análisis','~18 h',18,array['Tiempo','Colas']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria industrial economia estadistica administracion ingenieria de sistemas matematica sociologia ciencia de datos medicion de procesos. estadistica descriptiva. analisis de cuellos de botella. propuesta de mejoras. cronometro o app de notas. hoja de calculo. un editor de graficos.',$a51sld${"id": "cuanto-cuesta-una-cola-el-valor-del-tiempo-perdido-en-un-tramite", "area": "negocios", "areas2": ["ciudades", "industria"], "titulo": "¿Cuánto cuesta una cola? El valor del tiempo perdido en un trámite", "resumen": "Mide cuánto tiempo pasan las personas esperando en un trámite o servicio, conviértelo en un costo y propón cambios que reduzcan la espera.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Tiempo", "Colas"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Industrial", "Economía", "Estadística", "Administración", "Ingeniería de Sistemas", "Matemática", "Sociología", "Ciencia de Datos"], "problema": ["Hacer una cola parece un asunto menor, pero el tiempo de espera tiene un costo para quien espera y para quien atiende. Cuando miles de personas hacen colas cada día, el costo total es enorme.", "Pocas veces se mide, y por eso es difícil saber qué mejoras valen la pena."], "desarrollar": ["Elige un lugar donde haya colas, como una ventanilla, una cafetería o un paradero, y mide durante varios momentos cuánto esperan las personas y cuánto dura la atención, sin registrar datos personales.", "Calcula el tiempo total perdido, conviértelo en un valor aproximado usando un monto por hora que justifiques, y propón dos cambios simples, como horarios, más puntos de atención o reservas, y estima su efecto."], "ampliaciones": [{"titulo": "Modelo de colas", "aporta": "aplica un modelo simple de colas para estimar esperas."}, {"titulo": "Costo para el negocio", "aporta": "estima cuántos clientes se pierden por esperas largas."}, {"titulo": "Horas pico", "aporta": "analiza cómo cambia la espera según el momento del día."}], "objetivos": ["Medir tiempos con un método.", "Convertir tiempo en costo.", "Identificar cuellos de botella.", "Proponer mejoras."], "habilidades": ["Medición de procesos.", "Estadística descriptiva.", "Análisis de cuellos de botella.", "Propuesta de mejoras."], "herramientas": ["Cronómetro o app de notas.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Observa desde un lugar público, sin grabar ni fotografiar a las personas y sin anotar datos que las identifiquen.", "Si observas dentro de un establecimiento, pide permiso al responsable."], "otroSector": "El mismo análisis sirve para estudiar esperas en hospitales, transporte, atención en línea o procesos de una empresa."}$a51sld$::jsonb,59),
('la-economia-de-tu-campus-que-se-compra-y-se-vende-a-tu-alrededor','negocios',array['sociedad','ciudades']::text[],'La economía de tu campus: ¿qué se compra y se vende a tu alrededor?','Mapea los negocios y servicios que rodean tu universidad, qué venden, a qué precios y a quién, y estima cuánto dinero mueve esa pequeña economía.','Investigación','~22 h',22,array['Campus','Mercado local']::text[],array['investigar']::text[],'propios',NULL,'economia administracion sociologia estadistica marketing geografia contabilidad comunicaciones observacion de campo. clasificacion de datos. estimacion con supuestos. mapeo. hoja de calculo. un mapa en linea. cuaderno de campo.',$a52sld${"id": "la-economia-de-tu-campus-que-se-compra-y-se-vende-a-tu-alrededor", "area": "negocios", "areas2": ["sociedad", "ciudades"], "titulo": "La economía de tu campus: ¿qué se compra y se vende a tu alrededor?", "resumen": "Mapea los negocios y servicios que rodean tu universidad, qué venden, a qué precios y a quién, y estima cuánto dinero mueve esa pequeña economía.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Campus", "Mercado local"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Sociología", "Estadística", "Marketing", "Geografía", "Contabilidad", "Comunicaciones"], "problema": ["Alrededor de una universidad hay una economía propia: kioscos, fotocopiadoras, comedores, librerías, transporte y servicios. Miles de estudiantes consumen cada día, pero casi nadie sabe qué hay realmente ni cuánto se mueve.", "Conocerla permite ver oportunidades, brechas y cómo se relaciona la vida estudiantil con el comercio."], "desarrollar": ["Recorre las zonas cercanas a tu campus y registra qué tipos de negocios hay, qué venden y a qué precios aproximados, sin ingresar a zonas privadas ni anotar nombres de personas.", "Clasifica los negocios, haz un mapa simple, estima ventas diarias con supuestos razonables, calcula el gasto estudiantil mensual aproximado y destaca qué servicios faltan o abundan."], "ampliaciones": [{"titulo": "Lo que falta", "aporta": "identifica necesidades estudiantiles que no tienen oferta cercana."}, {"titulo": "Horarios", "aporta": "analiza en qué horas se concentra el consumo."}, {"titulo": "Comparar con otro campus", "aporta": "compara la economía de dos zonas universitarias."}], "objetivos": ["Observar y registrar con método.", "Clasificar negocios y servicios.", "Estimar el movimiento económico.", "Detectar oportunidades."], "habilidades": ["Observación de campo.", "Clasificación de datos.", "Estimación con supuestos.", "Mapeo."], "herramientas": ["Hoja de cálculo.", "Un mapa en línea.", "Cuaderno de campo."], "lineamientos": ["Registra solo información pública sobre negocios y no sobre personas, y evita fotografiar a los vendedores sin permiso.", "Presenta estimaciones como aproximaciones y no como cifras de ventas reales."], "otroSector": "El mismo método sirve para estudiar la economía de un mercado, un barrio, un parque industrial o un terminal."}$a52sld$::jsonb,60),
('vale-la-pena-pagar-por-un-curso-o-certificacion','negocios',array['educacion']::text[],'¿Vale la pena pagar por un curso o certificación?','Crea una forma de evaluar si un curso o certificación vale lo que cuesta, comparando precio, tiempo, contenido, reconocimiento y lo que podría aportar.','Análisis','~18 h',18,array['Educación','Inversión']::text[],array['investigar','resolver']::text[],'publicos',NULL,'economia educacion administracion psicologia estadistica contabilidad sociologia ingenieria de sistemas analisis multicriterio. lectura critica de ofertas. busqueda de informacion. argumentacion. hoja de calculo. paginas publicas de los cursos. una tabla comparativa.',$a53sld${"id": "vale-la-pena-pagar-por-un-curso-o-certificacion", "area": "negocios", "areas2": ["educacion"], "titulo": "¿Vale la pena pagar por un curso o certificación?", "resumen": "Crea una forma de evaluar si un curso o certificación vale lo que cuesta, comparando precio, tiempo, contenido, reconocimiento y lo que podría aportar.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Educación", "Inversión"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Educación", "Administración", "Psicología", "Estadística", "Contabilidad", "Sociología", "Ingeniería de Sistemas"], "problema": ["Hay una oferta enorme de cursos y certificaciones, algunos gratuitos y otros muy caros. No siempre es claro cuáles aportan algo y cuáles solo cuestan.", "Decidir con criterio exige comparar lo que se invierte, en dinero y en tiempo, con lo que se obtiene, sin caer en promesas exageradas."], "desarrollar": ["Elige tres cursos o certificaciones de un mismo tema, con información pública de precio, duración, contenido, reseñas y requisitos, y arma una tabla comparativa.", "Define criterios de evaluación con pesos, como utilidad, costo, reconocimiento y tiempo, puntúa cada opción y explica qué decidiría una persona con un presupuesto limitado."], "ampliaciones": [{"titulo": "Alternativas gratuitas", "aporta": "compara con recursos gratuitos equivalentes."}, {"titulo": "Señales de alerta", "aporta": "elabora una lista de señales de un curso poco confiable."}, {"titulo": "Costo del tiempo", "aporta": "añade el valor de las horas que exige el curso."}], "objetivos": ["Reunir información comparable.", "Definir criterios de evaluación.", "Puntuar alternativas.", "Justificar una decisión."], "habilidades": ["Análisis multicriterio.", "Lectura crítica de ofertas.", "Búsqueda de información.", "Argumentación."], "herramientas": ["Hoja de cálculo.", "Páginas públicas de los cursos.", "Una tabla comparativa."], "lineamientos": ["No afirmes que un curso funciona o es una estafa sin pruebas; presenta criterios y deja que cada persona decida.", "No incluyas datos de compra ni cuentas personales."], "otroSector": "El mismo método sirve para evaluar un posgrado, un software, un equipo o cualquier inversión de aprendizaje."}$a53sld$::jsonb,61),
('un-mercado-en-miniatura-simula-oferta-y-demanda-con-tu-grupo','negocios',array['educacion','ciencias']::text[],'Un mercado en miniatura: simula oferta y demanda con tu grupo','Organiza un juego donde unos hacen de vendedores y otros de compradores con costos y disposiciones a pagar ficticias, y observa cómo se forman los precios.','Simulación','~20 h',20,array['Mercado','Juego']::text[],array['crear','investigar']::text[],'ficticios',NULL,'economia educacion estadistica matematica psicologia administracion ingenieria de sistemas sociologia diseno de experimentos. graficos de oferta y demanda. analisis de resultados. facilitacion de grupos. tarjetas o papelitos. hoja de calculo. un editor de graficos.',$a54sld${"id": "un-mercado-en-miniatura-simula-oferta-y-demanda-con-tu-grupo", "area": "negocios", "areas2": ["educacion", "ciencias"], "titulo": "Un mercado en miniatura: simula oferta y demanda con tu grupo", "resumen": "Organiza un juego donde unos hacen de vendedores y otros de compradores con costos y disposiciones a pagar ficticias, y observa cómo se forman los precios.", "tipo": "Simulación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Mercado", "Juego"], "intencion": ["crear", "investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Economía", "Educación", "Estadística", "Matemática", "Psicología", "Administración", "Ingeniería de Sistemas", "Sociología"], "problema": ["La oferta y la demanda se explican con curvas, pero es más fácil entenderlas jugando. Cuando compradores y vendedores negocian, los precios se acercan a un punto de equilibrio sin que nadie lo dicte.", "Un experimento sencillo muestra por qué ocurre y qué pasa cuando cambian las condiciones."], "desarrollar": ["Reparte a cada participante una tarjeta con un costo de producción o un precio máximo ficticio, deja que negocien por rondas y registra los precios de cada transacción.", "Grafica cómo se acercan los precios al equilibrio, repite cambiando una condición, como un impuesto o una escasez, y explica los cambios observados."], "ampliaciones": [{"titulo": "Versión con programación", "aporta": "simula el mercado con un programa y compara con el juego."}, {"titulo": "Efecto de una regla", "aporta": "introduce un precio máximo y observa qué ocurre."}, {"titulo": "Resumen para enseñar", "aporta": "prepara una guía para repetir el juego en otro grupo."}], "objetivos": ["Diseñar un experimento de mercado.", "Registrar y graficar resultados.", "Comprender el equilibrio.", "Analizar el efecto de cambios."], "habilidades": ["Diseño de experimentos.", "Gráficos de oferta y demanda.", "Análisis de resultados.", "Facilitación de grupos."], "herramientas": ["Tarjetas o papelitos.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Usa montos ficticios y que la participación sea voluntaria; no incluyas dinero real.", "Explica a los participantes que es un juego de aprendizaje y no refleja todos los mercados."], "otroSector": "El mismo juego sirve para explicar subastas, asignación de recursos o fijación de precios en otros contextos."}$a54sld$::jsonb,62),
('por-que-suben-los-precios-en-ciertas-epocas','negocios',array['agricultura','sociedad']::text[],'¿Por qué suben los precios en ciertas épocas?','Analiza con datos públicos cómo cambian los precios de ciertos productos a lo largo del año y busca las razones de esas subidas y bajadas.','Análisis','~20 h',20,array['Estacionalidad','Precios']::text[],array['investigar']::text[],'publicos',NULL,'economia estadistica ciencia de datos ingenieria agroindustrial administracion matematica geografia ingenieria de sistemas analisis de series de tiempo. limpieza de datos. visualizacion. pensamiento critico. hoja de calculo o python. portales de datos publicos de precios. un editor de graficos.',$a55sld${"id": "por-que-suben-los-precios-en-ciertas-epocas", "area": "negocios", "areas2": ["agricultura", "sociedad"], "titulo": "¿Por qué suben los precios en ciertas épocas?", "resumen": "Analiza con datos públicos cómo cambian los precios de ciertos productos a lo largo del año y busca las razones de esas subidas y bajadas.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Estacionalidad", "Precios"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Estadística", "Ciencia de Datos", "Ingeniería Agroindustrial", "Administración", "Matemática", "Geografía", "Ingeniería de Sistemas"], "problema": ["Algunos productos suben de precio en ciertos meses, por cosechas, festividades, clima o demanda. Quienes compran lo notan, pero pocas veces se estudia con datos cuánto cambian ni por qué.", "Conocer estos patrones permite planificar compras, presupuestos y ventas."], "desarrollar": ["Elige dos o tres productos, como frutas, verduras o útiles escolares, descarga series públicas de precios por mes durante varios años y grafícalas.", "Identifica los meses de precios más altos y más bajos, busca explicaciones razonables y compara si el patrón se repite cada año, indicando cuáles explicaciones son hipótesis."], "ampliaciones": [{"titulo": "Calendario de compras", "aporta": "crea un calendario sugerido de cuándo conviene comprar cada producto."}, {"titulo": "Eventos especiales", "aporta": "analiza el efecto de una festividad o de un fenómeno climático."}, {"titulo": "Predicción simple", "aporta": "prueba un método sencillo para estimar el precio del próximo mes."}], "objetivos": ["Obtener y limpiar series de precios.", "Identificar patrones estacionales.", "Buscar explicaciones sustentadas.", "Comunicar los resultados."], "habilidades": ["Análisis de series de tiempo.", "Limpieza de datos.", "Visualización.", "Pensamiento crítico."], "herramientas": ["Hoja de cálculo o Python.", "Portales de datos públicos de precios.", "Un editor de gráficos."], "lineamientos": ["Cita la fuente y el periodo de los datos, y distingue entre lo que muestran y las explicaciones que propones.", "No presentes la predicción como un pronóstico confiable."], "otroSector": "El mismo análisis sirve para estudiar la estacionalidad del consumo de energía, de turismo o de matrículas."}$a55sld$::jsonb,63),
('la-pollada-cuanto-se-gana-realmente-en-una-actividad-para-recaud','negocios',array['sociedad']::text[],'La pollada: ¿cuánto se gana realmente en una actividad para recaudar fondos?','Calcula cuánto deja realmente una actividad de recaudación como una pollada, un bingo o una venta, contando costos, tiempo y riesgos, y cómo mejorar el resultado.','Análisis','~18 h',18,array['Recaudación','Eventos']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'contabilidad administracion economia ingenieria industrial trabajo social estadistica marketing sociologia presupuesto de eventos. analisis de escenarios. calculo de punto de equilibrio. comunicacion transparente. hoja de calculo. un editor de graficos. datos inventados.',$a56sld${"id": "la-pollada-cuanto-se-gana-realmente-en-una-actividad-para-recaud", "area": "negocios", "areas2": ["sociedad"], "titulo": "La pollada: ¿cuánto se gana realmente en una actividad para recaudar fondos?", "resumen": "Calcula cuánto deja realmente una actividad de recaudación como una pollada, un bingo o una venta, contando costos, tiempo y riesgos, y cómo mejorar el resultado.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Recaudación", "Eventos"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Contabilidad", "Administración", "Economía", "Ingeniería Industrial", "Trabajo Social", "Estadística", "Marketing", "Sociología"], "problema": ["En muchas comunidades y organizaciones se recauda fondos con actividades como polladas o rifas. Se ven llenas de gente, pero no siempre se sabe cuánto queda tras descontar insumos, alquileres, tiempo y lo que no se vendió.", "Hacer la cuenta con orden ayuda a decidir si la actividad vale la pena y cómo mejorar la ganancia."], "desarrollar": ["Inventa una actividad de recaudación y lista todos sus ingresos posibles y costos, como insumos, permisos, alquiler, publicidad y movilidad, incluyendo el tiempo voluntario con un valor referencial.", "Calcula la ganancia neta en un caso normal, otro con menos asistentes y otro con sobrante de comida, y propón tres cambios que aumenten lo recaudado."], "ampliaciones": [{"titulo": "Punto de equilibrio", "aporta": "calcula cuántas entradas hay que vender para no perder."}, {"titulo": "Comparar actividades", "aporta": "compara una pollada con una rifa o una venta de postres."}, {"titulo": "Rendición de cuentas", "aporta": "diseña un informe sencillo para mostrar a la comunidad cuánto se recaudó y en qué se usó."}], "objetivos": ["Listar ingresos y costos con orden.", "Calcular la ganancia neta.", "Analizar escenarios.", "Proponer mejoras y rendir cuentas."], "habilidades": ["Presupuesto de eventos.", "Análisis de escenarios.", "Cálculo de punto de equilibrio.", "Comunicación transparente."], "herramientas": ["Hoja de cálculo.", "Un editor de gráficos.", "Datos inventados."], "lineamientos": ["Usa un caso inventado y, si organizas una actividad real, cumple las normas de higiene, seguridad y permisos locales.", "Mantén transparencia con los fondos recaudados."], "otroSector": "El mismo análisis sirve para planificar cualquier evento de una organización, como un festival, una feria o una campaña."}$a56sld$::jsonb,64),
('como-pagamos-hoy-efectivo-billeteras-digitales-y-tarjetas','negocios',array['tecnologia','sociedad']::text[],'¿Cómo pagamos hoy? Efectivo, billeteras digitales y tarjetas','Investiga cómo pagan las personas en tu entorno, qué ventajas y problemas ven en el efectivo, las billeteras digitales y las tarjetas, y qué factores influyen en su elección.','Investigación','~20 h',20,array['Pagos','Digitalización']::text[],array['investigar']::text[],'propios',NULL,'economia ingenieria de sistemas administracion sociologia marketing estadistica comunicaciones derecho diseno de encuestas. analisis de datos. comprension de medios de pago. comunicacion clara. un formulario anonimo. hoja de calculo. informacion publica de comisiones.',$a57sld${"id": "como-pagamos-hoy-efectivo-billeteras-digitales-y-tarjetas", "area": "negocios", "areas2": ["tecnologia", "sociedad"], "titulo": "¿Cómo pagamos hoy? Efectivo, billeteras digitales y tarjetas", "resumen": "Investiga cómo pagan las personas en tu entorno, qué ventajas y problemas ven en el efectivo, las billeteras digitales y las tarjetas, y qué factores influyen en su elección.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Pagos", "Digitalización"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Ingeniería de Sistemas", "Administración", "Sociología", "Marketing", "Estadística", "Comunicaciones", "Derecho"], "problema": ["Los medios de pago han cambiado rápido: junto al efectivo ahora hay billeteras digitales, códigos QR y tarjetas. Pero no todos los usan, y los negocios pequeños a veces dudan en aceptarlos.", "Entender qué valoran las personas, como rapidez, seguridad o costo, ayuda a ver barreras y oportunidades."], "desarrollar": ["Diseña una encuesta anónima corta sobre cómo pagan en sus compras habituales, qué medios usan y por qué, y aplícala a una muestra pequeña de personas.", "Analiza los resultados por grupos, identifica ventajas y barreras de cada medio y escribe recomendaciones para un negocio pequeño que se pregunta si debería aceptar pagos digitales."], "ampliaciones": [{"titulo": "Visión del comerciante", "aporta": "entrevista a dos comerciantes sobre sus razones."}, {"titulo": "Costos de aceptar pagos", "aporta": "compara las comisiones y costos de cada medio con datos públicos."}, {"titulo": "Seguridad", "aporta": "elabora una guía de buenas prácticas para pagar con seguridad."}], "objetivos": ["Diseñar una encuesta anónima.", "Analizar hábitos de pago.", "Identificar barreras.", "Formular recomendaciones."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Comprensión de medios de pago.", "Comunicación clara."], "herramientas": ["Un formulario anónimo.", "Hoja de cálculo.", "Información pública de comisiones."], "lineamientos": ["La encuesta debe ser anónima y voluntaria, sin pedir números de cuentas, tarjetas ni datos bancarios.", "No promociones empresas concretas ni des asesoría financiera."], "otroSector": "El mismo estudio sirve para investigar cómo se adoptan otras tecnologías en comercios, colegios o instituciones."}$a57sld$::jsonb,65),
('cuanto-valdria-el-trabajo-del-hogar-que-no-se-paga','negocios',array['sociedad']::text[],'¿Cuánto valdría el trabajo del hogar que no se paga?','Calcula cuánto costaría pagar por el trabajo doméstico y de cuidado que se hace sin cobrar, como cocinar, limpiar y cuidar, y qué dice eso sobre cómo se valora ese trabajo.','Análisis','~18 h',18,array['Trabajo no remunerado','Cuidado']::text[],array['investigar']::text[],'propios',NULL,'economia sociologia trabajo social estadistica psicologia contabilidad administracion derecho registro de datos. valoracion economica. analisis critico. sensibilidad social. hoja de calculo. tarifas publicas de servicios. encuestas publicas de uso del tiempo.',$a58sld${"id": "cuanto-valdria-el-trabajo-del-hogar-que-no-se-paga", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Cuánto valdría el trabajo del hogar que no se paga?", "resumen": "Calcula cuánto costaría pagar por el trabajo doméstico y de cuidado que se hace sin cobrar, como cocinar, limpiar y cuidar, y qué dice eso sobre cómo se valora ese trabajo.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Trabajo no remunerado", "Cuidado"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Sociología", "Trabajo Social", "Estadística", "Psicología", "Contabilidad", "Administración", "Derecho"], "problema": ["Mucho del trabajo que sostiene a las familias, como cocinar, limpiar, cuidar a niños o a adultos mayores, no se paga y casi no aparece en las estadísticas económicas. Se hace principalmente en casa y muchas veces por mujeres.", "Ponerle un valor en soles no reemplaza su importancia, pero ayuda a visibilizarlo y a discutir cómo se reparte."], "desarrollar": ["Durante una semana registra cuánto tiempo se dedica en un hogar, el tuyo o uno ficticio, a distintas tareas de cuidado y trabajo doméstico, sin identificar a personas.", "Valora ese tiempo usando tarifas públicas de servicios equivalentes, calcula el monto semanal y anual, y reflexiona sobre cómo se reparte el trabajo y qué cambiaría si se reconociera económicamente."], "ampliaciones": [{"titulo": "Distintos métodos de valoración", "aporta": "compara valorar por costo de reemplazo y por costo de oportunidad."}, {"titulo": "Diferencias entre hogares", "aporta": "compara dos hogares ficticios con composiciones distintas."}, {"titulo": "Datos públicos", "aporta": "relaciona tus resultados con encuestas públicas de uso del tiempo."}], "objetivos": ["Registrar el uso del tiempo.", "Valorar el trabajo no pagado.", "Comparar métodos.", "Reflexionar sobre su reparto."], "habilidades": ["Registro de datos.", "Valoración económica.", "Análisis crítico.", "Sensibilidad social."], "herramientas": ["Hoja de cálculo.", "Tarifas públicas de servicios.", "Encuestas públicas de uso del tiempo."], "lineamientos": ["Trabaja con tu propio hogar solo si te sientes cómodo, o con un caso ficticio, y no expongas conflictos familiares.", "Presenta el valor como una forma de visibilizar y no como una medida de la dignidad de nadie."], "otroSector": "El mismo método sirve para valorar el trabajo voluntario, comunitario o de una organización sin fines de lucro."}$a58sld$::jsonb,66),
('en-que-gasta-tu-municipalidad-lee-un-presupuesto-publico','negocios',array['derecho','ciudades']::text[],'¿En qué gasta tu municipalidad? Lee un presupuesto público','Lee el presupuesto público de una municipalidad, descubre en qué se gasta el dinero de los vecinos y compara con las necesidades de la zona.','Análisis','~22 h',22,array['Presupuesto público','Transparencia']::text[],array['investigar']::text[],'publicos',NULL,'economia derecho ciencias politicas contabilidad administracion estadistica ingenieria civil sociologia lectura de presupuestos. busqueda en portales de transparencia. analisis de datos. comunicacion ciudadana. portales oficiales de transparencia. hoja de calculo. un editor de graficos.',$a59sld${"id": "en-que-gasta-tu-municipalidad-lee-un-presupuesto-publico", "area": "negocios", "areas2": ["derecho", "ciudades"], "titulo": "¿En qué gasta tu municipalidad? Lee un presupuesto público", "resumen": "Lee el presupuesto público de una municipalidad, descubre en qué se gasta el dinero de los vecinos y compara con las necesidades de la zona.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Presupuesto público", "Transparencia"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Derecho", "Ciencias Políticas", "Contabilidad", "Administración", "Estadística", "Ingeniería Civil", "Sociología"], "problema": ["Los municipios administran dinero público para obras y servicios, y por ley deben informar cómo lo usan. Pero esa información suele estar en tablas difíciles de leer.", "Aprender a leerla permite entender las prioridades de una zona y hacer preguntas informadas como ciudadano."], "desarrollar": ["Elige un municipio y busca en portales oficiales su presupuesto y ejecución, y clasifica los gastos por rubros, como limpieza, seguridad, obras y administración.", "Calcula qué porcentaje va a cada rubro y el gasto por habitante, compara con otro municipio similar y plantea tres preguntas que un vecino podría hacer a la gestión."], "ampliaciones": [{"titulo": "Presupuesto frente a ejecución", "aporta": "compara lo planificado con lo gastado realmente."}, {"titulo": "Obras visibles", "aporta": "relaciona una obra con su costo y su avance."}, {"titulo": "Resumen para vecinos", "aporta": "prepara una hoja informativa en lenguaje sencillo."}], "objetivos": ["Ubicar información presupuestal oficial.", "Clasificar y calcular gastos.", "Comparar municipios.", "Formular preguntas informadas."], "habilidades": ["Lectura de presupuestos.", "Búsqueda en portales de transparencia.", "Análisis de datos.", "Comunicación ciudadana."], "herramientas": ["Portales oficiales de transparencia.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Usa solo datos públicos y evita acusar de mal uso del dinero: solo describe y pregunta.", "Cita la fuente y fecha del presupuesto, y aclara que no verificas la ejecución en el terreno."], "otroSector": "La misma lectura sirve para presupuestos de universidades, de ministerios o de organizaciones con fondos públicos."}$a59sld$::jsonb,67),
('puede-un-negocio-ser-rentable-y-resolver-un-problema-social','negocios',array['sociedad']::text[],'¿Puede un negocio ser rentable y resolver un problema social?','Estudia cómo algunos negocios generan ingresos y a la vez resuelven un problema social, y diseña un modelo posible donde ambas cosas se sostengan.','Investigación','~22 h',22,array['Emprendimiento social','Impacto']::text[],array['investigar','crear']::text[],'publicos',NULL,'administracion economia trabajo social sociologia ingenieria industrial derecho comunicaciones contabilidad analisis de modelos. diseno de impacto. pensamiento critico. presentacion de propuestas. informes publicos de organizaciones. un lienzo de modelo de negocio. hoja de calculo.',$a60sld${"id": "puede-un-negocio-ser-rentable-y-resolver-un-problema-social", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Puede un negocio ser rentable y resolver un problema social?", "resumen": "Estudia cómo algunos negocios generan ingresos y a la vez resuelven un problema social, y diseña un modelo posible donde ambas cosas se sostengan.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Emprendimiento social", "Impacto"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Administración", "Economía", "Trabajo Social", "Sociología", "Ingeniería Industrial", "Derecho", "Comunicaciones", "Contabilidad"], "problema": ["Hay emprendimientos que no solo buscan ganar, sino también resolver un problema, como el acceso a alimentos, a educación o a empleo. Pero resolver un problema social suele costar, y no siempre es claro cómo hacerlo sin depender de donaciones.", "Entender cómo lo logran ayuda a diseñar propuestas más sostenibles."], "desarrollar": ["Elige dos o tres ejemplos de emprendimientos con impacto social, con información pública, y analiza qué problema resuelven, a quién sirven, cómo ganan dinero y qué los hace sostenibles.", "Con lo aprendido, diseña un modelo para un problema de tu entorno, describe cómo se financiaría, cómo medirías el impacto y qué riesgos tendría."], "ampliaciones": [{"titulo": "Medir el impacto", "aporta": "propón indicadores para saber si el problema realmente mejora."}, {"titulo": "Tensiones", "aporta": "analiza qué pasa cuando el interés económico y el social chocan."}, {"titulo": "Alianzas", "aporta": "identifica qué instituciones podrían apoyar el modelo."}], "objetivos": ["Analizar modelos de emprendimiento social.", "Entender su financiamiento.", "Diseñar un modelo propio.", "Definir cómo medir su impacto."], "habilidades": ["Análisis de modelos.", "Diseño de impacto.", "Pensamiento crítico.", "Presentación de propuestas."], "herramientas": ["Informes públicos de organizaciones.", "Un lienzo de modelo de negocio.", "Hoja de cálculo."], "lineamientos": ["Usa información pública y reconoce los límites de lo que se puede medir desde fuera.", "No presentes la propuesta como una solución definitiva a un problema complejo."], "otroSector": "El mismo análisis sirve para estudiar organizaciones sin fines de lucro, proyectos comunitarios o programas de responsabilidad social."}$a60sld$::jsonb,68),
('que-le-conviene-digitalizar-a-un-negocio-de-barrio','negocios',array['tecnologia']::text[],'¿Qué le conviene digitalizar a un negocio de barrio?','Evalúa qué procesos de un negocio pequeño convendría pasar a herramientas digitales, como ventas, inventario o pedidos, comparando el costo, el beneficio y la facilidad de cada uno.','Plan','~22 h',22,array['Digitalización','Pequeño negocio']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria de sistemas administracion ingenieria industrial economia contabilidad marketing comunicaciones ciencia de datos analisis de procesos. evaluacion de tecnologias. priorizacion. comunicacion a no tecnicos. diagramas simples de procesos. hoja de calculo. informacion publica de herramientas.',$a61sld${"id": "que-le-conviene-digitalizar-a-un-negocio-de-barrio", "area": "negocios", "areas2": ["tecnologia"], "titulo": "¿Qué le conviene digitalizar a un negocio de barrio?", "resumen": "Evalúa qué procesos de un negocio pequeño convendría pasar a herramientas digitales, como ventas, inventario o pedidos, comparando el costo, el beneficio y la facilidad de cada uno.", "tipo": "Plan", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Digitalización", "Pequeño negocio"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería de Sistemas", "Administración", "Ingeniería Industrial", "Economía", "Contabilidad", "Marketing", "Comunicaciones", "Ciencia de Datos"], "problema": ["Muchas bodegas, talleres y tiendas siguen usando cuaderno y calculadora. Digitalizar todo de golpe puede ser caro y complicado, pero hay mejoras pequeñas que ahorran tiempo y evitan pérdidas.", "El reto es elegir por dónde empezar según lo que de verdad necesita el negocio y lo que puede pagar."], "desarrollar": ["Inventa un negocio de barrio y describe sus procesos actuales, como ventas, cuentas de fiado, inventario y pedidos a proveedores, indicando qué problemas tiene cada uno.", "Para cada proceso propón una herramienta digital sencilla, estima costo y beneficio, y ordena una ruta de tres pasos para digitalizar según prioridad y facilidad."], "ampliaciones": [{"titulo": "Capacitación", "aporta": "diseña cómo se enseñaría a usar las herramientas al personal."}, {"titulo": "Riesgos", "aporta": "analiza los riesgos de depender de la tecnología, como cortes de internet."}, {"titulo": "Hoja para pedir ayuda", "aporta": "prepara una lista de preguntas para consultar a un proveedor."}], "objetivos": ["Describir procesos del negocio.", "Identificar problemas y oportunidades.", "Evaluar costo y beneficio.", "Priorizar una ruta."], "habilidades": ["Análisis de procesos.", "Evaluación de tecnologías.", "Priorización.", "Comunicación a no técnicos."], "herramientas": ["Diagramas simples de procesos.", "Hoja de cálculo.", "Información pública de herramientas."], "lineamientos": ["Usa un negocio inventado y no recomiendes productos comerciales concretos como los únicos posibles.", "Considera la protección de los datos de clientes y el acceso real a internet en el barrio."], "otroSector": "El mismo plan sirve para digitalizar procesos de un colegio, una posta, una asociación o una pequeña empresa."}$a61sld$::jsonb,69),
('cuanto-dinero-mueve-una-feria-o-un-festival-en-tu-barrio','negocios',array['ciudades','arte']::text[],'¿Cuánto dinero mueve una feria o un festival en tu barrio?','Estima cuánto dinero se mueve en una feria, festival o mercado de tu barrio, quiénes se benefician y qué costos y efectos trae para la zona.','Análisis','~20 h',20,array['Ferias','Economía local']::text[],array['investigar']::text[],'propios',NULL,'economia administracion sociologia marketing estadistica arquitectura comunicaciones contabilidad observacion de campo. estimacion con supuestos. analisis de impacto local. comunicacion de resultados. cuaderno de campo. hoja de calculo. un editor de graficos.',$a62sld${"id": "cuanto-dinero-mueve-una-feria-o-un-festival-en-tu-barrio", "area": "negocios", "areas2": ["ciudades", "arte"], "titulo": "¿Cuánto dinero mueve una feria o un festival en tu barrio?", "resumen": "Estima cuánto dinero se mueve en una feria, festival o mercado de tu barrio, quiénes se benefician y qué costos y efectos trae para la zona.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Ferias", "Economía local"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Sociología", "Marketing", "Estadística", "Arquitectura", "Comunicaciones", "Contabilidad"], "problema": ["Una feria o un festival atrae visitantes, y con ellos compras de comida, productos y transporte. Pero casi nunca se calcula cuánto dinero circula ni quién se beneficia más.", "Hacerlo ayuda a valorar estos eventos y a entender sus costos, como basura, ruido o tráfico."], "desarrollar": ["Elige una feria o un evento de tu zona, cuenta con observación cuántas personas asisten por hora, cuántos puestos hay y cuánto se vende aproximadamente según los precios.", "Estima el movimiento de dinero del evento, clasifica por tipo de ingreso y de beneficiario, y lista los costos que recaen en la comunidad, concluyendo cómo mejorar el balance."], "ampliaciones": [{"titulo": "Visitantes de otras zonas", "aporta": "estima cuánto dinero llega desde fuera del barrio."}, {"titulo": "Efecto en negocios cercanos", "aporta": "observa cómo cambian las ventas de las tiendas vecinas."}, {"titulo": "Propuesta de mejora", "aporta": "diseña un plan para que el evento deje más y moleste menos."}], "objetivos": ["Observar y contar con método.", "Estimar el movimiento económico.", "Identificar beneficiarios y costos.", "Proponer mejoras."], "habilidades": ["Observación de campo.", "Estimación con supuestos.", "Análisis de impacto local.", "Comunicación de resultados."], "herramientas": ["Cuaderno de campo.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Observa desde zonas públicas, sin grabar a las personas ni pedir datos privados a los comerciantes, y presenta cifras como estimaciones.", "Pide permiso a los organizadores si vas a consultar información interna del evento."], "otroSector": "El mismo método sirve para estimar el movimiento económico de un partido, un concierto, un mercado de temporada o un evento universitario."}$a62sld$::jsonb,70)
